steps.starter:
{{pins}}
#include <DHT.h>

DHT sensor(DHT_PIN, DHT11);  // use DHT22 if yours is white

void setup() {
  Serial.begin(9600);
  sensor.begin();
}

void loop() {
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.print(" C   Humidity: ");
  Serial.print(humidity);
  Serial.println(" %");
  delay(2000);
}

