{{pins}}
#include <DHT.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 screen(128, 64, &Wire, -1);
DHT sensor(DHT_PIN, DHT11);

void setup() {
  Serial.begin(9600);
  sensor.begin();
  if (!screen.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("Screen not found: check the wiring.");
  }
  screen.setTextColor(SSD1306_WHITE);
}

void loop() {
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();

  screen.clearDisplay();
  screen.setTextSize(1);
  screen.setCursor(0, 0);
  screen.println("Weather station");
  screen.setTextSize(2);
  screen.setCursor(0, 20);
  screen.print(temperature, 1);
  screen.println(" C");
  screen.print(humidity, 0);
  screen.println(" %");

  // How does it feel?
  screen.setTextSize(1);
  screen.setCursor(0, 56);
  if (isnan(temperature)) {
    screen.print("No sensor!");
  } else if (temperature > 28) {
    screen.print("Hot! Drink water.");
  } else if (temperature < 15) {
    screen.print("Chilly: grab a jumper.");
  } else {
    screen.print("Just right.");
  }
  screen.display();
  delay(2000);
}
